};

// Save config
global.set('describe', describe, 'memoryOnly');

// Clear user and more
global.set('auth',{},'memoryOnly');
global.set('user',{},'memoryOnly');
global.set('form',{},'memoryOnly');

// Prepare project query
return {
    'topic': '',
    'payload': '',
    'filename': '/data/.config.projects.json'
};

if (typeof msg.login === 'string' && msg.login !== "" && 
    typeof msg.pass === 'string' && msg.pass !== ""
) {
    msg.login = msg.login.toLowerCase();
    let hash = global.get('auth["' + msg.login + '"]["pass"]', 'memoryOnly');
    if (typeof hash === 'string') {
        msg.hash = hash;

        return msg;
    }
}

return msg;

global.set('user["' + msg._client.socketId + '"]',{
    'login':msg.login,
    'level':global.get('auth["' + msg.login + '"]["level"]','memoryOnly')||'',
    'lang':global.get('auth["' + msg.login + '"]["lang"]','memoryOnly')||'',
    'time':Date.now()
}, 'memoryOnly');

delete msg.login;
delete msg.pass;

msg.payload = true;

return msg;

global.set('user["' + msg._client.socketId + '"]',undefined,'memoryOnly');

delete msg.login;
delete msg.pass;

msg.payload = false;

return msg;

/* Limit to 6 hours */
let limit = Date.now() - (6*60*60*1000);
msg.topic = limit;

let users = global.get('user', 'memoryOnly');
if (typeof users === 'object') {
    for (const user in users) {
        if (typeof global.get('auth["' + users[user]["login"] + '"]["level"]', 'memoryOnly') !== 'string' 
        || users[user]["time"] < limit 
        || (typeof msg.login === 'string' && msg.login === users[user]["login"])
        ) {
            global.set('user["' + user + '"]', undefined, 'memoryOnly');
            global.set('form["' + user + '"]', undefined, 'memoryOnly');
            msg.payload = user;
            node.send(msg);
        }
    }
}

msg.payload = 'cleaned';

return msg;

flow.set('has_admin', false, 'memoryOnly');

if (typeof msg.payload === 'object') {
    for (const login in msg.payload) {
        if (typeof msg.payload[login]["pass"] === 'string'
            && typeof msg.payload[login]["pass"] === 'string'
            && typeof msg.payload[login]["level"] === 'string'
        ) {
            if (typeof msg.payload[login]["lang"] !== 'string') {
                msg.payload[login]["lang"] = 'fr';
            }
            if (typeof msg.payload[login]["telegram"] !== 'string') {
                msg.payload[login]["telegram"] = '';
            }

            if (msg.payload[login]["level"] === 'admin') {
                flow.set('has_admin', true, 'memoryOnly');
            }

            global.set('auth["' + login + '"]',{
                'pass': msg.payload[login]["pass"],
                'level': msg.payload[login]["level"],
                'lang': msg.payload[login]["lang"],
                'telegram': msg.payload[login]["telegram"]
            }, 'memoryOnly');
        }
    }
}

return msg;

delete msg.tag; // use msg.name only

// On unwanted state, stop here
if (msg.payload.match((new RegExp('^(connect|change|lost)$'))) === null) {
    if (typeof msg.hmi.id === 'string' && msg.hmi.id !== '') {
        global.set('user["' + msg.hmi.id + '"]', undefined, 'memoryOnly');
        global.set('form["' + msg.hmi.id + '"]', undefined, 'memoryOnly');
    }

    return;
}

// On connect or lost connection, go to auth page
if (msg.payload === 'connect' || msg.payload === 'lost') {
    msg.payload = global.get('describe.pages.auth.name', 'memoryOnly') || '';

    return [null, null, msg];
}

// Prepare ui
msg.menus = {};
msg.titles = {};
msg.payload = {
    'pages': {
        'show': [],
        'hide': []
    }
};

let pages = global.get('describe.pages', 'memoryOnly');
if (typeof pages !== 'object') {
    return;
}

// check user page right
let allowed = false;
let s = 0;
let h = 0;
for (const page in pages) {
    if (typeof pages[page]['level'][msg.hmi.level] === 'boolean') {
        if (pages[page]['level'][msg.hmi.level] === true) {
            msg.menus[page] = true;
            msg.payload.pages.show[s++] = pages[page]['name'];
        } else {
            msg.menus[page] = false;
            msg.payload.pages.hide[h++] = pages[page]['name'];
        }
    } else {
        if (global.get('describe.pages.auth.name', 'memoryOnly') === pages[page]['name']) {
            msg.menus[page] = true;
            msg.payload.pages.show[s++] = pages[page]['name'];
        } else {
            msg.menus[page] = false;
            msg.payload.pages.hide[h++] = pages[page]['name'];
        }
    }
    msg.titles[page] = msg.dictionary.option_page[page];

    if (pages[page]['name'] === msg.hmi.name) {
        msg.page_title = msg.dictionary.option_page[page];
        msg.page_lang = msg.hmi.lang;
    }

    if (pages[page]['name'] === msg.hmi.name && pages[page]['level'][msg.hmi.level] === true) {
        allowed = true;
    }
}

if (allowed === false) {
    msg.hmi.name = global.get('describe.pages.auth.name', 'memoryOnly');
    msg.page_title = msg.dictionary.option_page.auth;
    msg.page_lang = msg.hmi.lang;
}

// user plant
global.set('form["' + msg.hmi.id + '"]["ts"]', Date.now(), 'memoryOnly');

// page process
let newMsg = {
    'topic': '',
    'payload': msg.hmi.name,
    'hmi': msg.hmi,
    'dictionary': msg.dictionary,
    '_client': msg._client
};

// ui menu
msg.version = global.get('describe.app.version', 'memoryOnly') || '0.0.0';
msg.title = msg.page_title + ' - ' + global.get('describe.app.title', 'memoryOnly');
msg.full = msg.title + ' v' + msg.version + ' for ' + msg.vendor;

delete msg.dictionary;

return [msg, newMsg, null];

if (msg.payload !== '' && typeof global.get('describe.pages["' + msg.payload + '"]["name"]', 'memoryOnly') === 'string') {
    msg.name = global.get('describe.pages["' + msg.payload + '"]["name"]', 'memoryOnly');
    msg.payload = msg.name;

    return msg;
} else {
    let default_browser = {
        'lang': msg.payload,
        'time': Date.now()
    }
    global.set('browser["' + msg._client.socketId + '"]', default_browser, 'memoryOnly');

    let time = Date.now() - 60000;
    let browsers = global.get('browser', 'memoryOnly') || {};
    for (const browser in browsers) {
        if (browsers[browser]['time'] < time) {
            global.set('browser["' + browser + '"]', undefined, 'memoryOnly');
        }
    }

    return;
}

let memorized = {
    'auth': {},
    'entity': {},
    'mqtt': {},
    'name': { 'room': {}, 'device': {}, 'entity': {} }
}

// Copy backup or at least init
for (const key in memorized) {
    global.set(key, (global.get(key, 'default') || memorized[key]), 'memoryOnly');
}

// Reset variables
global.set('browser', {}, 'memoryOnly');
global.set('describe', { 'project': '', 'app': {}, 'pages': {}, 'enum': {}, 'elements': {} }, 'memoryOnly');
global.set('dictionary', {}, 'memoryOnly');
global.set('form', {}, 'memoryOnly');
global.set('user', {}, 'memoryOnly');

// start
msg.payload = {
    'pages': {},
    'enum': {},
    'dictionary': {}
};

return msg;

msg.topic = '';
msg.payload = ''; 
msg.class = 'remove';
msg.enabled = false;

node.send(msg);

if (typeof msg.check === 'string'
    && msg.hmi.level !== ''
    && msg.hmi.name === global.get('describe.pages["' + msg.check + '"]["name"]', 'memoryOnly')
    && global.get('describe.pages["' + msg.check + '"]["level"]["' + msg.hmi.level + '"]', 'memoryOnly') === true
) {
    msg.class = '';
    msg.enabled = true;

    //global.set('form["' + msg.hmi.id + '"]["tab"]', msg.check, 'memoryOnly');

    delete msg.check;

    await new Promise(resolve => setTimeout(resolve, 50)); // wait 50ms

    return msg;
} else {
    //global.set('form["' + msg.hmi.id + '"]["name"]', '', 'memoryOnly');
}

if (typeof msg.payload !== 'object') {
    msg.payload = {};
}
if (typeof msg.payload.pages !== 'object') {
    msg.payload.pages = {};
}
if (typeof msg.payload.enum !== 'object') {
    msg.payload.enum = {};
}
if (typeof msg.payload.dictionary !== 'object') {
    msg.payload.dictionary = {};
}

let describe = global.get('describe', 'memoryOnly') || {};
for (const p in msg.payload.pages) {
    describe.pages[p] = msg.payload.pages[p];
}
for (const e in msg.payload.enum) {
    describe.enum[e] = msg.payload.enum[e];
}

global.set('describe', describe, 'memoryOnly');

let dictionary = global.get('dictionary', 'memoryOnly') || {};
for (const lang in msg.payload.dictionary) {
    if (typeof dictionary[lang] !== 'object') {
        dictionary[lang] = {};
    }
    if (typeof msg.payload.dictionary[lang] === 'object') {
        for (const group in msg.payload.dictionary[lang]) {
            if (typeof dictionary[lang][group] !== 'object') {
                dictionary[lang][group] = {};
            }
            if (typeof msg.payload.dictionary[lang][group] === 'object') {
                for (const sentence in msg.payload.dictionary[lang][group]) {
                    // custom sentence overwrite existing ones
                    dictionary[lang][group][sentence] = msg.payload.dictionary[lang][group][sentence];
                }
            }
        }
    }
}

global.set('dictionary', dictionary, 'memoryOnly');

return msg;

let dictionary = global.get('dictionary', 'memoryOnly') || {};

// First clean up "en"
if (typeof msg.payload['en'] === 'object') {
    for (const group in msg.payload['en']) {
        if (typeof dictionary['en'][group] !== 'object') {
            dictionary['en'][group] = {};
        }
        if (typeof msg.payload['en'][group] === 'object') {
            for (const sentence in msg.payload['en'][group]) {
                // custom sentence overwrite existing ones
                dictionary['en'][group][sentence] = msg.payload['en'][group][sentence];
            }
        }
    }
}

// then fill all others langs
for (const lang in msg.payload) {
    if (lang !== 'en') {
        if (typeof dictionary[lang] !== 'object') {
            dictionary[lang] = {};
        }

        // fisrt fill current lang qith "en" sentences
        for (const group in dictionary['en']) {
            if (typeof dictionary[lang][group] !== 'object') {
                dictionary[lang][group] = {};
            }
            for (const sentence in dictionary['en'][group]) {
                // custom sentence overwrite existing ones
                dictionary[lang][group][sentence] = dictionary['en'][group][sentence];
            }
        }

        // then fill current lang with custom sentences
        if (typeof msg.payload[lang] === 'object') {
            for (const group in msg.payload[lang]) {
                if (typeof dictionary[lang][group] !== 'object') {
                    dictionary[lang][group] = {};
                }
                if (typeof msg.payload[lang][group] === 'object') {
                    for (const sentence in msg.payload[lang][group]) {
                        // custom sentence overwrite existing ones
                        dictionary[lang][group][sentence] = msg.payload[lang][group][sentence];
                    }
                }
            }
        }
    }
}

global.set('dictionary', dictionary, 'memoryOnly');

//await new Promise(resolve => setTimeout(resolve, 10));

msg.payload = '';

return msg;

if (typeof msg.hmi === 'undefined') {
    msg.hmi = {
        'name': '',
        'id': '',
        'login': '',
        'level': '',
        'lang': 'en',
        'time': Date.now()
    };
}
msg.dictionary = global.get('dictionary.en', 'memoryOnly') || {};

if (typeof msg.name === 'string') {
    msg.hmi.name = msg.name;
    delete msg.name;
}

if (typeof msg._client === 'object' && typeof msg._client.socketId === 'string') {
    let browser_lang = global.get('browser["' + msg._client.socketId + '"]["lang"]', 'memoryOnly');
    if (typeof browser_lang === 'string') {
        msg.hmi.lang = browser_lang;
    }
    msg.hmi.id = msg._client.socketId;

    let user = global.get('user["' + msg.hmi.id + '"]', 'memoryOnly');
    if (typeof user === 'object') {
        global.set('user["' + msg.hmi.id + '"]["time"]', Date.now(), 'memoryOnly');
        msg.hmi = Object.assign({}, msg.hmi, user);
    }
}

if (msg.tab === 99) {
    global.set('form', {}, 'memoryOnly');
}

delete msg.reset; //???

let current = global.get('dictionary["' + msg.hmi.lang + '"]', 'memoryOnly');
if (typeof current === 'object') {
    // current lang overwrite en
    msg.dictionary = { ...msg.dictionary, ...current };
}

return msg;

// Prepare project query
if (typeof msg.payload.activeProject === 'string') {
    return {
        'topic': '',
        'payload': '',
        'filename': '/data/projects/' + msg.payload.activeProject + '/package.json'
    };
}

return;

msg.broker = {};

let mqtt = global.get('mqtt', 'memoryOnly');
if (typeof mqtt == 'object' && mqtt.enabled == true) {
    if (mqtt.host.length > 0
        && mqtt.port > 0
        && mqtt.topic.length > 0
    ) {
        msg.broker = {
            'broker': mqtt.host,
            'port': mqtt.port,
            'clientid': global.get('describe.app.project', 'memoryOnly') || 'dknr',
            'birth': {
                'topic': mqtt.topic + '/kernel/state',
                'payload': 'online',
                'qos': 0,
                'retain': false
            },
            'close': {
                'topic': mqtt.topic + '/kernel/state',
                'payload': 'offline',
                'qos': 0,
                'retain': false
            },
            'will': {
                'topic': mqtt.topic + '/kernel/state',
                'payload': 'will',
                'qos': 0,
                'retain': false
            },
            'force': true
        };

        if (mqtt.username.length > 0 && mqtt.password.length > 0) {
            msg.broker.username = mqtt.username;
            msg.broker.password = mqtt.password;
        }

        msg.action = 'connect';
        node.status({fill:"green",shape:"ring",text:"settings ok"});

        node.send(msg);

        msg.action = 'subscribe';
        msg.topic = mqtt.topic + '/#';
        msg.payload = '';

        node.send(msg);

    } else {
        global.set('mqtt["enabled"]', false, 'memoryOnly');
        node.status({ fill: "red", shape: "ring", text: "settings ko" });
    }
} else {
    msg.action = 'disconnect';

    node.send(msg);
}

return;

let mqtt = global.get('mqtt', 'memoryOnly') || {};
if (typeof mqtt.enabled === 'boolean' && 
    mqtt.enabled === true && 
    typeof msg.repeat === 'boolean' &&
    msg.repeat === false &&
    typeof msg.payload === 'object'
) {
    let newMsg = {
        'topic': mqtt.topic + '/' + msg.payload.uid,
        'payload': msg.payload,
    };

    return newMsg;
}

return;

msg.broker = {};

let mqtt = global.get('mqtt', 'memoryOnly');
if (typeof mqtt == 'object' && mqtt.enabled == true && mqtt.teleinfo != '') {
    if (mqtt.host.length > 0
        && mqtt.port > 0
        && mqtt.teleinfo.length > 0
    ) {
        msg.broker = {
            'broker': mqtt.host,
            'port': mqtt.port,
            'clientid': 'teleinfo' + global.get('describe.app.project', 'memoryOnly') || 'dknr',
            'force': true
        };

        if (mqtt.username.length > 0 && mqtt.password.length > 0) {
            msg.broker.username = mqtt.username;
            msg.broker.password = mqtt.password;
        }

        msg.action = 'connect';
        node.status({fill:"green",shape:"ring",text:"settings ok"});

        node.send(msg);

        msg.action = 'subscribe';
        msg.topic = mqtt.teleinfo + '/#';
        msg.payload = '';

        node.send(msg);

    } else {
        global.set('mqtt["enabled"]', false, 'memoryOnly');
        node.status({ fill: "red", shape: "ring", text: "settings ko" });
    }
} else {
    msg.action = 'disconnect';

    node.send(msg);
}

return;

let res = {
    'topic':'',
    'payload': {}
};

if (typeof msg.payload === 'object' && 
    typeof msg.payload.ADCO === 'object' && 
    typeof msg.payload.ADCO.raw === 'string'
) {
    node.status({ text: msg.payload.ADCO.raw });

    for (const key in msg.payload){
        if (key === 'PTEC') {
            // Convert HC to bin
            msg.payload[key]['value'] = msg.payload[key]['value'] === 'HC' ? 0 : 1;
            msg.payload[key]['unit'] = 'b';
        }

        res.payload.id = key;
        res.payload.source = 'teleinfo';
        res.payload.parent = msg.payload.ADCO.raw;
        res.payload.unit = msg.payload[key]['unit'];
        res.payload.value = msg.payload[key]['value'];
        res.payload.name = msg.payload[key]['name'];
        res.payload.seen = Date.now();

        node.send(res);
    }
}

return;

// Stop loop from elsewhere
let stop = flow.get('stop', 'memoryOnly') || false;

// required to build uid
if (stop === true ||
    typeof msg.payload !== 'object' || 
    typeof msg.payload.source !== 'string' || 
    typeof msg.payload.parent !== 'string' || 
    typeof msg.payload.id !== 'string' || 
    typeof msg.payload.value === 'undefined'
) {

    return;
}

// default keys
let template = {
    'uid': '',
    'source': '',
    'id': '',
    'parent': '',
    'value': '',
    'type': '',
    'room': '',
    'element': '',
    'unit': '',
    'seen': 0,
    'hidden': 0
};

// rebuilt some keys
if (msg.payload.parent.slice(0, msg.payload.source.length) !== msg.payload.source) {
    // dot not add source on loop
    msg.payload.parent = msg.payload.source + '_' + msg.payload.parent;
}
msg.payload.uid = msg.payload.parent + '_' + msg.payload.id;

// Convert boolean to int
if (typeof msg.payload.value === 'boolean') {
    msg.payload.value = msg.payload.value ? 1 : 0;
}

// get existing entity
let entity = global.get('entity["' + msg.payload.uid + '"]', 'memoryOnly') || {};
let protect = ['room'];

// set all entity fields
entity = {...template, ...entity};

// check if value changes
msg.repeat = entity['value'] === msg.payload.value ? true : false;

for (const k in msg.payload) {
    // set entity name if entity is new
    if (k === 'name' && entity.id === '') {
        let name = global.get('name["entity"]', 'memoryOnly') || {};
        if (typeof name[msg.payload.uid] !== 'string' || name[msg.payload.uid] === '') {
            name[msg.payload.uid] = msg.payload.name;
            global.set('name["entity"]', name, 'memoryOnly')
        }
    }

    if (typeof template[k] !== 'undefined') {
        if (protect.includes(k) && entity[k] !== '') {
